=== FILE: rr_arbiter_props.sv ===
// Formal wrapper and properties for rr_arbiter (interface_spec.md).
// Each property is tagged with the spec requirement it checks.
`default_nettype none
module rr_arbiter_formal (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // ------------------------------------------------------------------
    // Reference model of the priority order: last+1, last+2, last (mod 3)
    // ------------------------------------------------------------------
    function [2:0] f_expect;
        input [1:0] l;
        input [2:0] r;
        reg   [1:0] p0, p1, p2;
        begin
            p0 = (l == 2'd0) ? 2'd1 : (l == 2'd1) ? 2'd2 : 2'd0;
            p1 = (l == 2'd0) ? 2'd2 : (l == 2'd1) ? 2'd0 : 2'd1;
            p2 = (l == 2'd0) ? 2'd0 : (l == 2'd1) ? 2'd1 : 2'd2;
            if (r[p0])      f_expect = 3'b001 << p0;
            else if (r[p1]) f_expect = 3'b001 << p1;
            else if (r[p2]) f_expect = 3'b001 << p2;
            else            f_expect = 3'b000;
        end
    endfunction

    function [1:0] f_idx;
        input [2:0] g;
        begin
            f_idx = g[0] ? 2'd0 : g[1] ? 2'd1 : 2'd2;
        end
    endfunction

    // ------------------------------------------------------------------
    // Only constraint: reset is asserted in the pre-history state
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume (!rst_n);

    // ------------------------------------------------------------------
    // Wait counters for RR-BOUND (cleared by reset, grant, or dropped req)
    // ------------------------------------------------------------------
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;

    always @(posedge clk) begin
        if (!rst_n) begin
            f_wait0 <= 2'd0;
            f_wait1 <= 2'd0;
            f_wait2 <= 2'd0;
        end else begin
            if (req[0] && !grant[0]) f_wait0 <= (f_wait0 == 2'd3) ? 2'd3 : f_wait0 + 2'd1;
            else                     f_wait0 <= 2'd0;
            if (req[1] && !grant[1]) f_wait1 <= (f_wait1 == 2'd3) ? 2'd3 : f_wait1 + 2'd1;
            else                     f_wait1 <= 2'd0;
            if (req[2] && !grant[2]) f_wait2 <= (f_wait2 == 2'd3) ? 2'd3 : f_wait2 + 2'd1;
            else                     f_wait2 <= 2'd0;
        end
    end

    // ------------------------------------------------------------------
    // Combinational properties (valid once a reset edge has happened)
    // ------------------------------------------------------------------
    always @(*) begin
        if (f_past_valid) begin
            // last is 0, 1 or 2 (port table; induction helper)
            assert (last != 2'd3);
            // [req:RR-IDLE]
            if (req == 3'b000) assert (grant == 3'b000);
            // [req:RR-PICK] at most one bit high
            assert ((grant & (grant - 3'b001)) == 3'b000);
            // [req:RR-PICK] exactly one bit when any request
            if (req != 3'b000) assert (grant != 3'b000);
            // [req:RR-PICK] first requester in rotation order
            assert (grant == f_expect(last, req));
            // [req:RR-ONLY-REQUESTERS]
            assert ((grant & ~req) == 3'b000);
            // [req:RR-BOUND]
            assert (f_wait0 <= 2'd2);
            assert (f_wait1 <= 2'd2);
            assert (f_wait2 <= 2'd2);
            if (req[0] && f_wait0 == 2'd2) assert (grant[0]);
            if (req[1] && f_wait1 == 2'd2) assert (grant[1]);
            if (req[2] && f_wait2 == 2'd2) assert (grant[2]);
        end
    end

    // ------------------------------------------------------------------
    // Sequential properties
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:RR-RESET]
            if (!$past(rst_n)) assert (last == 2'd2);
            // [req:RR-ROTATE]
            if ($past(rst_n) && $past(grant) != 3'b000)
                assert (last == f_idx($past(grant)));
            // [req:RR-HOLD]
            if ($past(rst_n) && $past(grant) == 3'b000)
                assert (last == $past(last));
            // [req:RR-YIELD]
            if ($past(rst_n) && $past(grant[0]) && (req[2:1] != 2'b00))
                assert (!grant[0]);
            if ($past(rst_n) && $past(grant[1]) && ({req[2], req[0]} != 2'b00))
                assert (!grant[1]);
            if ($past(rst_n) && $past(grant[2]) && (req[1:0] != 2'b00))
                assert (!grant[2]);
        end
    end

    // ------------------------------------------------------------------
    // Covers: every assertion antecedent is reachable (non-vacuity)
    // ------------------------------------------------------------------
    always @(*) begin
        if (f_past_valid) begin
            cover (req == 3'b000);
            cover (grant == 3'b001);
            cover (grant == 3'b010);
            cover (grant == 3'b100);
            cover (req == 3'b111 && last == 2'd0);
            cover (req == 3'b111 && last == 2'd1);
            cover (req == 3'b111 && last == 2'd2);
            cover (req[0] && f_wait0 == 2'd2);
            cover (req[1] && f_wait1 == 2'd2);
            cover (req[2] && f_wait2 == 2'd2);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // mid-run reset from a non-default state
            cover ($past(f_past_valid) && !$past(rst_n) && $past(last) != 2'd2);
            // real rotation (last changes)
            cover ($past(rst_n) && $past(grant) != 3'b000
                   && $past(last) != f_idx($past(grant)));
            // hold at a non-reset value
            cover ($past(rst_n) && $past(grant) == 3'b000 && last != 2'd2);
            // yield antecedents
            cover ($past(rst_n) && $past(grant[0]) && (req[2:1] != 2'b00));
            cover ($past(rst_n) && $past(grant[1]) && ({req[2], req[0]} != 2'b00));
            cover ($past(rst_n) && $past(grant[2]) && (req[1:0] != 2'b00));
        end
    end
endmodule
`default_nettype wire
=== END FILE ===
